INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT142-S4-Q10$batch13$, 142, 4, 10, $batch13$Evaluate$batch13$, $batch13$In 2005, paleontologist Mary Schweitzer made headlines when she reported finding preserved soft tissue in the bones of a Tyrannosaurus rex dinosaur. Analysis of the collagen proteins from the T. rex showed them to be similar to the collagen proteins in modern-day chickens. Schweitzer’s discovery therefore adds to the mountain of evidence that dinosaurs are closely related to birds.$batch13$, $batch13$The answer to which one of the following questions would be most useful to know in order to evaluate the argument?$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=142 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$How rare is it to find preserved soft tissue in the bones of a dinosaur?$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Is there any evidence at all against the claim that dinosaurs are closely related to birds?$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$How likely is it for animals that are not closely related to each other to have similar collagen proteins?$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Is it possible that T. rex is more closely related to modern-day chickens than to certain other types of dinosaurs?$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$Before Schweitzer’s discovery, did researchers suppose that the collagen proteins in T. rex and chickens might be similar?$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The discovery adds to the evidence that dinosaurs are closely related to birds.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Collagen proteins from a T. rex were similar to collagen proteins in modern chickens.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$Similar proteins count as evidence of a close relationship only if unrelated animals rarely share them. If many unrelated animals have similar collagen, the match means little.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Ask how common similar collagen is among animals that aren't closely related.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$How rare the find was doesn't change what the proteins show.$batch13$), ($batch13$B$batch13$, $batch13$Contrary evidence elsewhere doesn't affect whether this finding adds support.$batch13$), ($batch13$C$batch13$, $batch13$If unrelated animals often have similar collagen, the match is weak evidence. If they rarely do, it's strong.$batch13$), ($batch13$D$batch13$, $batch13$T. rex being closer to chickens than to some dinosaurs would still fit the conclusion. It doesn't test the evidence.$batch13$), ($batch13$E$batch13$, $batch13$What researchers expected beforehand doesn't affect what the match shows.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT142-S4-Q10$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
